var e=class e{constructor(e){this.element=e}setExpanded(e){return this.element.setAttribute(`aria-expanded`,String(e)),this}setHidden(e){return this.element.setAttribute(`aria-hidden`,String(e)),this}setHasPopup(e=`menu`){return this.element.setAttribute(`aria-haspopup`,e),this}setModal(e){return this.element.setAttribute(`aria-modal`,String(e)),this}setRole(e){return this.element.setAttribute(`role`,e),this}removeAttributes(...e){return e.forEach(e=>this.element.removeAttribute(e)),this}static createManager(t){return new e(t)}};export{e as t};